package org.example.bookmark;

import jakarta.persistence.EntityManager;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
@Transactional
class BookmarkReadNoteStageTest {
    @Autowired MockMvc mvc;
    @Autowired JdbcTemplate jdbc;
    @Autowired EntityManager em;
    @Autowired ObjectMapper mapper;

    @Test
    void readsNoteWhileStillWritingBothColumns() throws Exception {
        mvc.perform(put("/api/posts/2/bookmark")
                .header("Authorization", "Bearer tok-kimjava")
                .contentType("application/json")
                .content("{\"memo\":\"note-value\"}"))
                .andExpect(status().isOk());
        jdbc.update("UPDATE bookmark SET memo='stale-old-server' WHERE member_id=2 AND post_id=2");
        em.clear();
        var response = mvc.perform(get("/api/me/bookmarks?size=100")
                .header("Authorization", "Bearer tok-kimjava"))
                .andExpect(status().isOk()).andReturn();
        var items = mapper.readTree(response.getResponse().getContentAsString()).get("items");
        boolean found = false;
        for (var item : items) {
            if (item.get("postId").asLong() == 2L) {
                assertEquals("note-value", item.get("memo").asText());
                found = true;
            }
        }
        assertEquals(true, found);
    }
}

